const $=s=>document.querySelector(s);
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>{const active=x===b;x.setAttribute('aria-selected',active);$('#'+x.dataset.tab).hidden=!active;});});
function calculate(expression){
 const s=expression.replaceAll('×','*').replaceAll('÷','/').replaceAll('π','pi').replace(/\s+/g,'').toLowerCase();
 const tokens=s.match(/(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?|[a-z]+|[()+*/^%\-]/g)||[];
 if(tokens.join('')!==s||!tokens.length||tokens.length>200)throw Error('Check the calculation.');let i=0;
 function atom(){const t=tokens[i++];if(t==='('){const v=sum();if(tokens[i++]!==')')throw Error('Missing closing bracket.');return v;}if(t==='pi')return Math.PI;if(t==='e')return Math.E;if(t&&/^(\d|\.)/.test(t))return Number(t);const f={sqrt:Math.sqrt,abs:Math.abs,ln:Math.log,log:Math.log10,sin:x=>Math.sin(x*Math.PI/180),cos:x=>Math.cos(x*Math.PI/180),tan:x=>Math.tan(x*Math.PI/180)}[t];if(f){if(tokens[i++]!=='(')throw Error('Use brackets after a function.');const v=sum();if(tokens[i++]!==')')throw Error('Missing closing bracket.');return f(v);}throw Error('Check the calculation.');}
 function power(){let v=atom();while(tokens[i]==='%'){i++;v/=100;}if(tokens[i]==='^'){i++;v=v**unary();}return v;}
 function unary(){if(tokens[i]==='-'){i++;return -unary();}if(tokens[i]==='+'){i++;return unary();}return power();}
 function product(){let v=unary();while(['*','/'].includes(tokens[i])){const op=tokens[i++],n=unary();v=op==='*'?v*n:v/n;}return v;}
 function sum(){let v=product();while(['+','-'].includes(tokens[i])){const op=tokens[i++],n=product();v=op==='+'?v+n:v-n;}return v;}
 const value=sum();if(i!==tokens.length||!Number.isFinite(value))throw Error('No finite result. Check brackets and values.');return Number(value.toPrecision(12));
}
function equals(){try{const expression=$('#expression').value,result=calculate(expression);$('#answer').textContent=result;const li=document.createElement('li');li.textContent=expression+' = '+result;$('#history').prepend(li);while($('#history').children.length>10)$('#history').lastChild.remove();}catch(e){$('#answer').textContent=e.message;}}
for(const key of ['sin(','cos(','tan(','sqrt(','log(','(',')','^','%','C','7','8','9','÷','⌫','4','5','6','×','π','1','2','3','-','abs(','0','.','+','ln(','=']){const b=document.createElement('button');b.textContent=key.replace('(','');if(key==='(')b.textContent='(';b.onclick=()=>{const input=$('#expression');if(key==='=')return equals();if(key==='C'){input.value='';$('#answer').textContent='0';return;}if(key==='⌫'){input.value=input.value.slice(0,-1);return;}input.setRangeText(key,input.selectionStart,input.selectionEnd,'end');input.focus();};$('#keys').append(b);}
$('#expression').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();equals();}};
const languages={en:'English',ja:'Japanese 日本語',ms:'Malay Bahasa Melayu',fr:'French Français',ko:'Korean 한국어'};
for(const id of ['source','target'])for(const [code,name] of Object.entries(languages)){const o=document.createElement('option');o.value=code;o.textContent=name;$('#'+id).append(o);}$('#target').value='ja';
$('#swap').onclick=()=>{const a=$('#source').value;$('#source').value=$('#target').value;$('#target').value=a;if($('#output-text').value){$('#input-text').value=$('#output-text').value;$('#output-text').value='';}};
async function api(path,body){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Fieldstation':'tools'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not complete the request.');return data;}
fetch('/api/tools/status').then(r=>r.json()).then(s=>{$('#model-status').textContent=s.ready?'All five languages are ready offline.':'Language packs are being installed. Refresh this page when downloads finish.';$('#translate').disabled=!s.ready;}).catch(()=>{$('#model-status').textContent='Unable to check language packs.';$('#translate').disabled=true;});
$('#translate').onclick=async()=>{$('#translate').disabled=true;$('#output-text').value='';$('#translation-status').textContent='Translating on the Pi…';try{const r=await api('/api/tools/translate',{source:$('#source').value,target:$('#target').value,text:$('#input-text').value});$('#output-text').value=r.text;$('#translation-status').textContent=r.pivot?'Translated offline through English.':'Translated offline.';}catch(e){$('#translation-status').textContent=e.message;}finally{$('#translate').disabled=false;}};
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#output-text').value);$('#translation-status').textContent='Copied.';}catch{$('#output-text').select();$('#translation-status').textContent='Press Ctrl+C to copy the selected translation.';}};
document.querySelectorAll('[data-app]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/tools/launch',{app:b.dataset.app});$('#document-status').textContent='Opened on the Pi desktop. Close the document window to return.';}catch(e){$('#document-status').textContent=e.message;}finally{b.disabled=false;}});
